CREATE OR REPLACE VIEW Fre_VIfr_TInquery_Offers AS
 SELECT
        O.Id,
        I.Id Inqry_Id, I.Num Inqry_Num, I.dDate Inqry_Date,
        O.Id Offer_Id, O.Num Offer_Num, O.dDate Offer_Date,
        C.Id Cont_Id , C.Num Cont_Num , C.LName Cont_Name
   FROM Fre_MOffer       O ,
        Fre_MInqry       I ,
        Crm_Cont         C
  WHERE O.Inqry_Id=I.Id
    AND O.Cont_Id =C.Id;

CREATE OR REPLACE VIEW Fre_VIfr_TJob_Offers AS
 SELECT
        JO.Id,
        J.Id Job_Id  , J.Num Job_Num  , J.dDate Job_Date  ,
        I.Id Inqry_Id, I.Num Inqry_Num, I.dDate Inqry_Date,
        O.Id Offer_Id, O.Num Offer_Num, O.dDate Offer_Date,
        C.Id Cont_Id , C.Num Cont_Num , C.Name  Cont_Name
   FROM Fre_Ifr_JobOffer JO,
        Fre_Ifr_Job      J ,
        Fre_MOffer       O ,
        Fre_MInqry       I ,
        Mng_Cont         C
  WHERE JO.Job_Id =J.Id
    AND JO.Ofer_Id=O.Id
    AND Inqry_Id  =I.Id
    AND JO.Cont_Id=C.Id;

CREATE OR REPLACE VIEW Fre_VLfr_TJob_Offers AS
 SELECT
        O.Id         ,
        J.Id Job_Id  , J.Num Job_Num  , J.dDate Job_Date  ,
        C.Id Cont_Id , C.Num Cont_Num , C.Name  Cont_Name ,
        I.Id Inqry_Id, I.Num Inqry_Num, I.dDate Inqry_Date,
        O.Id Offer_Id, O.Num Offer_Num, O.dDate Offer_Date
   FROM Fre_Lfr_Job      J ,
        Fre_MOffer       O ,
        Fre_MInqry       I ,
        Mng_Cont         C
  WHERE J.Ofer_Id =O.Id
    AND Inqry_Id  =I.Id
    AND J.Cont_Id =C.Id;

