        J.Job_Cons    , J.Job_Qnt      , J.Job_Price       , J.Job_WNet          , J.Job_WGros   , J.Job_WChrg    , J.Job_Volume   , J.Job_Amt     ,
        J.Job_CAmt    , J.Job_Comm     , J.Job_CComm       , J.Job_ETD           , J.Job_ETA     , J.Job_ATD      , J.Job_ATA      , J.User_Id     ,
        J.User_UGrp_Id, J.User_PGrp_Id , J.User_Gender_Id  , J.User_Status_Id    , J.User_Logon  , J.User_Name    , J.Status_Id    , J.Status_Name ,
        J.Status_Date , J.Status_Rem   , J.Del_Status_Id   , J.Del_Status_Name   , J.Del_Num     , J.Del_Date     , J.Del_Person   ,
        J.Job_DCust   , J.Job_DueDate  , J.Job_MNum        , J.Job_MDate         , J.Job_HNum    , J.Job_HDate    , J.Job_ENum     , J.Job_EDate   ,
        J.Job_FNum    , J.Job_FDate    , J.AirLine_Id      , J.AirLine_Name      , J.ShipLine_Id , J.ShipLine_Name, J.Job_nRef     , J.Job_BRef    ,
        J.Job_POrder  , J.Track_Id     , J.Track_Name      , J.Job_LDM           , J.Job_CBM     , J.Job_CMRDate  , J.Pack_Id      , J.Pack_Name   ,
        J.KDocType_Id , J.KDocType_Name, J.Job_KDocNum     , J.Job_KDocDate      , J.Job_Waybill , J.IDocType_Id  , J.IDocType_Name, J.Job_IDocNum ,
        J.Job_IDocDate, J.ODocType_Id  , J.ODocType_Name   , J.Job_ODocNum       , J.Job_ODocDate, J.Job_TripNo   , J.TType_Id     , J.TType_Name  ,
        J.Job_Rel_Id  , J.Job_Rem      , J.PShare_Status_Id, J.PShare_Status_Name, J.Job_Ins_User, J.Job_Ins_Date , J.Job_Upd_User , J.Job_Upd_Date,
        STRING_AGG(O.Offer_Num , ', ') WITHIN GROUP (ORDER BY O.Offer_Id) AS Offer_Num ,
        STRING_AGG(O.Offer_Date, ', ') WITHIN GROUP (ORDER BY O.Offer_Id) AS Offer_Date,
        STRING_AGG(O.Inqry_Num , ', ') WITHIN GROUP (ORDER BY O.Offer_Id) AS Inqry_Num ,
        STRING_AGG(O.Inqry_Date, ', ') WITHIN GROUP (ORDER BY O.Offer_Id) AS Inqry_Date,
        STRING_AGG(O.Cont_Id   , ', ') WITHIN GROUP (ORDER BY O.Offer_Id) AS Cont_Id   ,
        STRING_AGG(O.Cont_Num  , ', ') WITHIN GROUP (ORDER BY O.Offer_Id) AS Cont_Num  ,
        STRING_AGG(O.Cont_Name , ', ') WITHIN GROUP (ORDER BY O.Offer_Id) AS Cont_Name
   FROM Fre_VIfr_Job J INNER JOIN Fre_VIfr_TJob_Offers O ON O.Job_Id = J.Job_Id
 GROUP BY 
        J.Job_Id      , J.Period_Id    , J.Period_Num      , J.Period_SDate      , J.Period_EDate, J.Period_Name  ,
        J.Dept_Id     , J.Dept_Name    , J.Unit_Id         , J.Unit_Name         , J.Oper_Id     , J.Oper_Name    , J.Curn_Id      , J.Curn_Name   ,
        J.Curn_Rate   , J.Mode_Id      , J.Mode_Name       , J.Job_Num           , J.Job_Date    , J.Job_Descr    ,
        J.D_Year      , J.D_Month      , J.D_DayOfMonth    , J.D_DayOfYear       , J.D_DayOfWeek , J.D_YearMonth  ,
        J.OCntry_Id   , J.OCntry_Name  , J.OContinent      , J.OContinent_Code   ,
        J.OCity_Id    , J.OCity_Name   , J.OPort_Id        , J.OPort_Name        , J.OSPort_Id   , J.OSPort_Name  ,
        J.OAPort_Id   , J.OAPort_Name  , J.Job_OName       , J.Job_OAddress      ,
        J.DCntry_Id   , J.DCntry_Name  , J.DContinent      , J.DContinent_Code   ,
        J.DCity_Id    , J.DCity_Name   , J.DPort_Id        , J.DPort_Name        , J.DSPort_Id   , J.DSPort_Name  ,
        J.DAPort_Id   , J.DAPort_Name  , J.Job_DName       , J.Job_DAddress      ,
        J.ITerm_Id    , J.ITerm_Name   , J.PTerm_Id        , J.PTerm_Name        , J.Comod_Id    , J.Comod_Name   , J.Job_vComd    , J.Job_Ship    ,
        J.Job_Cons    , J.Job_Qnt      , J.Job_Price       , J.Job_WNet          , J.Job_WGros   , J.Job_WChrg    , J.Job_Volume   , J.Job_Amt     ,
        J.Job_CAmt    , J.Job_Comm     , J.Job_CComm       , J.Job_ETD           , J.Job_ETA     , J.Job_ATD      , J.Job_ATA      , J.User_Id     ,
        J.User_UGrp_Id, J.User_PGrp_Id , J.User_Gender_Id  , J.User_Status_Id    , J.User_Logon  , J.User_Name    , J.Status_Id    , J.Status_Name ,
        J.Status_Date , J.Status_Rem   , J.Del_Status_Id   , J.Del_Status_Name   , J.Del_Num     , J.Del_Date     , J.Del_Person   ,
        J.Job_DCust   , J.Job_DueDate  , J.Job_MNum        , J.Job_MDate         , J.Job_HNum    , J.Job_HDate    , J.Job_ENum     , J.Job_EDate   ,
        J.Job_FNum    , J.Job_FDate    , J.AirLine_Id      , J.AirLine_Name      , J.ShipLine_Id , J.ShipLine_Name, J.Job_nRef     , J.Job_BRef    ,
        J.Job_POrder  , J.Track_Id     , J.Track_Name      , J.Job_LDM           , J.Job_CBM     , J.Job_CMRDate  , J.Pack_Id      , J.Pack_Name   ,
        J.KDocType_Id , J.KDocType_Name, J.Job_KDocNum     , J.Job_KDocDate      , J.Job_Waybill , J.IDocType_Id  , J.IDocType_Name, J.Job_IDocNum ,
        J.Job_IDocDate, J.ODocType_Id  , J.ODocType_Name   , J.Job_ODocNum       , J.Job_ODocDate, J.Job_TripNo   , J.TType_Id     , J.TType_Name  ,
        J.Job_Rel_Id  , J.Job_Rem      , J.PShare_Status_Id, J.PShare_Status_Name, J.Job_Ins_User, J.Job_Ins_Date , J.Job_Upd_User , J.Job_Upd_Date;

CREATE OR REPLACE VIEW Fre_VIfr_DBCR AS
 SELECT
        DC.Id                DBCR_Id              , JF.Job_Id         ,
        JF.Period_Id         JF_Period_Id         , JF.Period_Num       JF_Period_Num     , JF.Period_SDate  , JF.Period_EDate  ,
        JF.Period_Name       JF_Period_Name       , JF.Dept_Id          JF_Dept_Id        , JF.Dept_Name       JF_Dept_Name     ,
        JF.Oper_Id           JF_Oper_Id           , JF.Oper_Name        JF_Oper_Name      , JF.Curn_Rate       JF_Curn_Rate     ,
        JF.Unit_Id           JF_Unit_Id           , JF.Unit_Name        JF_Unit_Name      , JF.Curn_Id         JF_Curn_Id       ,
        JF.Curn_Name         JF_Curn_Name         , JF.Mode_Id        , JF.Mode_Name      , JF.Job_Num       , JF.Job_Date      ,
        JF.Job_Descr       , JF.ITerm_Id          , JF.ITerm_Name     , JF.PTerm_Id       , JF.PTerm_Name    ,
        JF.OCntry_Id       , JF.OCntry_Name       , JF.OContinent     , JF.OContinent_Code,
        JF.OCity_Id        , JF.OCity_Name        , JF.OPort_Id       , JF.OPort_Name     , JF.OSPort_Id     ,
        JF.OSPort_Name     , JF.OAPort_Id         , JF.OAPort_Name    , JF.Job_OName      , JF.Job_OAddress  ,
        JF.DCntry_Id       , JF.DCntry_Name       , JF.DContinent     , JF.DContinent_Code,
        JF.DCity_Id        , JF.DCity_Name        , JF.DPort_Id       , JF.DPort_Name     , JF.DSPort_Id     ,
        JF.DSPort_Name     , JF.DAPort_Id         , JF.DAPort_Name    , JF.Job_DName      , JF.Job_DAddress  , JF.Comod_Id      ,
        JF.Comod_Name      , JF.Job_vComd         , JF.Job_Ship       , JF.Job_Cons       , JF.Job_Qnt       , JF.Job_Price     ,
        JF.Job_WNet        , JF.Job_WGros         , JF.Job_WChrg      , JF.Job_Volume     , JF.Job_Amt       , JF.Job_CAmt      ,
        JF.Job_Comm        , JF.Job_CComm         , JF.Job_ETD        , JF.Job_ETA        , JF.Job_ATD       , JF.Job_ATA       ,                 
        JF.User_Id         , JF.User_UGrp_Id      , JF.User_PGrp_Id   , JF.User_Gender_Id , JF.User_Status_Id, JF.User_Logon    ,
        JF.User_Name       , JF.Status_Id           JF_Status_Id      , JF.Status_Name      JF_Status_Name   , JF.Status_Date   ,
        JF.Status_Rem      , JF.Del_Status_Id     , JF.Del_Status_Name, JF.Del_Num        , JF.Del_Date      , JF.Del_Person    ,
        JF.Job_DCust       , JF.Job_DueDate       , JF.Job_MNum       , JF.Job_MDate      , JF.Job_HNum      , JF.Job_HDate     ,
        JF.Job_ENum        , JF.Job_EDate         , JF.Job_FNum       , JF.Job_FDate      , JF.AirLine_Id    , JF.AirLine_Name  ,
        JF.ShipLine_Id     , JF.ShipLine_Name     , JF.Job_nRef       , JF.Job_BRef       , JF.Job_POrder    , JF.Track_Id      ,
        JF.Track_Name      , JF.Job_LDM           , JF.Job_CBM        , JF.Job_CMRDate    , JF.Pack_Id       , JF.Pack_Name     ,
        JF.KDocType_Id     , JF.KDocType_Name     , JF.Job_KDocNum    , JF.Job_KDocDate   , JF.Job_Waybill   , JF.IDocType_Id   ,
        JF.IDocType_Name   , JF.Job_IDocNum       , JF.Job_IDocDate   , JF.ODocType_Id    , JF.ODocType_Name , JF.Job_ODocNum   ,
        JF.Job_ODocDate    , JF.Job_TripNo        , JF.TType_Id       , JF.TType_Name     , JF.Job_Rel_Id    , JF.Job_Rem       ,
        JF.PShare_Status_Id, JF.PShare_Status_Name, JF.Job_Ins_User   , JF.Job_Ins_Date   , JF.Job_Upd_User  , JF.Job_Upd_Date  ,
        DC.nOrd              DBCR_nOrd            , DC.Num              DBCR_Num          , DC.dDate           DBCR_dDate       ,
        DP.Id                Dept_Id              , DP.Name             Dept_Name         , OP.Id              Oper_Id          ,
        OP.Name              Oper_Name            , U.Id                Unt_Id            , U.Name             Unt_Name         ,
        To_Number_Compat(To_Char(DC.dDate,'YYYY'))         D_Year            , To_Number_Compat(To_Char(DC.dDate,'MM'))      D_Month          ,
        To_Number_Compat(To_Char(DC.dDate,'DD'))           D_DayOfMonth      , To_Number_Compat(To_Char(DC.dDate,'DDD'))     D_DayOfYear      ,
        To_Number_Compat(To_Char(DC.dDate,'D'))            D_DayOfWeek       , To_Char(DC.dDate,'YYYY-MM')            D_YearMonth      ,
        Loc.Id                Loc_Id              , Loc.Name            Loc_Name          , TrT.Id             Trt_Id           ,
        TrT.Name              Trt_Name            , C.Id                Cont_Id           , C.Name             Cont_Name        ,
        S.Id                  Serv_Id             , S.Name              Serv_Name         , I.Id               Item_Id          ,
        I.LName               Item_Name           , Un.Id               Unit_Id           , Un.Name            Unit_Name        ,
        CR.Id                 Curn_Id             , CR.Name             Curn_Name         , ST.Id              Status_Id        ,
        ST.Name               Status_Name         , DC.Curn_Rate        DBCR_Curn_Rate    , DC.Qnt             DBCR_Qnt         ,
        DC.Price              DBCR_Price          , DC.CAmt             DBCR_CAmt         , DC.Amt             DBCR_Amt         ,
        DC.nRef               DBCR_nRef           , DC.dRef             DBCR_dRef         , DC.Rem             DBCR_Rem         ,
        DC.IFre_Id            IFre_Id             , DC.DFre_Id          DFre_Id           , DC.CFre_Id         CFre_Id          ,
        DC.Dept_RId           Dept_RId            , DC.Unit_RId         Unit_RId          , DC.Job_RId         Job_RId          ,
        DC.Ord_Id             Ord_Id              , DC.Waybill          DBCR_Waybill      , DC.Ins_User        DBCR_Ins_User    ,
        DC.Ins_Date           DBCR_Ins_Date       , DC.Upd_User         DBCR_Upd_User     , DC.Upd_Date        DBCR_Upd_Date    ,
        DC.Period_Id 
   FROM Fre_Ifr_DBCR  DC ,
        Fre_VIfr_Job  JF ,
        Cpy_Unit      U  ,
        Cpy_Dept      DP ,
        Cpy_Oper      OP ,
        Fre_Cod_Loc   Loc,
        Fin_Cod_Trt   TrT,
        Mng_Cont      C  ,
        Mng_Serv      S  ,
        Stor_Item     I  ,
        Cpy_Cod_Unit  Un ,
        Mng_Curn      CR ,
        Phs_Cod_YesNo ST
  WHERE DC.Job_Id          =JF.Job_Id
    AND COALESCE(JF.Dept_Id  ,0)=DP.Id
    AND COALESCE(JF.Oper_Id  ,0)=OP.Id
    AND COALESCE(JF.Unit_Id  ,0)=U.Id
    AND COALESCE(DC.Loc_Id   ,1)=Loc.Id
    AND COALESCE(DC.Trt_Id   ,0)=Trt.Id
    AND COALESCE(DC.Cont_Id  ,0)=C.Id
    AND COALESCE(DC.Serv_Id  ,0)=S.Id
    AND COALESCE(DC.Item_Id  ,0)=I.Id
    AND COALESCE(DC.Unit_Id  ,1)=Un.Id
    AND COALESCE(DC.Curn_Id  ,1)=CR.Id
    AND COALESCE(DC.Status_Id,2)=ST.Id;

CREATE OR REPLACE VIEW Fre_VLfr_Job AS
 SELECT
        JF.Id         Job_Id         ,
        P.Id          Period_Id      , P.Num       Period_Num     , P.SDate         Period_SDate   , P.EDate           Period_EDate   ,
        P.Name        Period_Name    ,
        DP.Id         Dept_Id        , DP.Name     Dept_Name      , UN.Id           Unit_Id        , UN.Name           Unit_Name      ,
        OP.Id         Oper_Id        , OP.Name     Oper_Name      ,
        O.Id          Ofer_Id        , O.Num       Offer_Num      , O.dDate         Offer_Date      , 
        MQ.Id         Inqry_Id       , MQ.Num      Inqry_Num      , MQ.dDate        Inqry_Date      , 
        C.Id          Cont_Id        , C.Num       Cont_Num       , C.Title         Cont_Title      , C.Name           Cont_Name      ,
        C.LName       Cont_LName     , C.Owner     Cont_Owner     , C.Contact       Cont_Contact    , C.dLmt           Cont_dLmt      ,
        C.nLmt        Cont_nLmt      , C.Repr_Id   Cont_Repr_Id   , C.Cost_Id       Cont_Cost_Id    , C.AccDbt_Id      Cont_AccDbt_Id ,
        C.AccCrd_Id   Cont_AccCrd_Id , C.Rem       Cont_Rem       ,
        CR.Id         Cont_RId       , CR.Num      Cont_RNum      , CR.Title        Cont_RTitle     , CR.Name          Cont_RName     ,
        CR.LName      Cont_RLName    , CR.Owner    Cont_ROwner    , CR.Contact      Cont_RContact   , CR.dLmt          Cont_RdLmt     ,
        CR.nLmt       Cont_RnLmt     , CR.Repr_Id  Cont_RRepr_Id  , CR.Cost_Id      Cont_RCost_Id   , CR.AccDbt_Id     Cont_RAccDbt_Id,
        CR.AccCrd_Id  Cont_RAccCrd_Id, CR.Rem      Cont_RRem      ,
        DRV.Id        Driv_Id        , DRV.NatId   Driv_NatId     , DRV.FName       Driv_FName      , DRV.LName        Driv_LName     ,
        DRV.Father    Driv_Father    , DRV.Mother  Driv_Mother    , DRV.Phone       Driv_Phone      , DRV.Mobile       Driv_Mobile    ,
        TRK.Id        Truk_Id        , TRK.Num     Truk_Num       , TRK.City        Truk_City       , TRK.Color        Truk_Color     ,
        TRK.Brand     Truk_Brand     , TRK.Year    Truk_Year      ,
        Emp.Id        Emp_Id         , Emp.Num     Emp_Num        , Emp.NNum        Emp_NNum        , Emp.PNum         Emp_PNum       ,
        Emp.INum      Emp_INum       , Emp.AttNum  Emp_AttNum     , Emp.PCard       Emp_PCard       , Emp.Name         Emp_Name       ,
        Emp.aName     Emp_aName      , Emp.eName   Emp_eName      , Emp.Father      Emp_Father      , Emp.Mother       Emp_Mother     ,
        JF.Num        Job_Num        , JF.dDate    Job_Date       , JF.Descr        Job_Descr      ,
        To_Number_Compat(To_Char(JF.dDate,'YYYY'))        D_Year         ,
        To_Number_Compat(To_Char(JF.dDate,'MM'))          D_Month        ,
        To_Number_Compat(To_Char(JF.dDate,'DD'))          D_DayOfMonth   ,
        To_Number_Compat(To_Char(JF.dDate,'DDD'))         D_DayOfYear    ,
        To_Number_Compat(To_Char(JF.dDate,'D'))           D_DayOfWeek    ,
        To_Char(JF.dDate,'YYYY-MM')                D_YearMonth    ,
        CTRC.Id       Contr_Id       , CTRC.Num    Contr_Num      , CTRC.dDate      Contr_Date  ,
        CTRS.Id       Contr_RId      , CTRS.Num    Contr_RNum     , CTRS.dDate      Contr_RDate ,
        IT.Id         ITerm_Id       , IT.Name     ITerm_Name     , PT.Id           PTerm_Id    , PT.Name              PTerm_Name     ,
        OCntr.Id      OCntry_Id      , OCntr.Name  OCntry_Name    , OCntr.Continent OContinent  , OCntr.Continent_Code OContinent_Code,
        OCty.Id       OCity_Id       , OCty.Name   OCity_Name     ,
        OPrt.Id       OPort_Id       , OPrt.Name   OPort_Name     , OSPrt.Id        OSPort_Id   , OSPrt.Name           OSPort_Name    ,
        OAPrt.Id      OAPort_Id      , OAPrt.Name  OAPort_Name    , JF.OName        Job_OName   , JF.OAddress          Job_OAddress   ,
        DCntr.Id      DCntry_Id      , DCntr.Name  DCntry_Name    , DCntr.Continent DContinent  , DCntr.Continent_Code DContinent_Code,
        DCty.Id       DCity_Id       , DCty.Name   DCity_Name     ,
        DPrt.Id       DPort_Id       , DPrt.Name   DPort_Name     , DSPrt.Id        DSPort_Id   , DSPrt.Name           DSPort_Name    ,
        DAPrt.Id      DAPort_Id      , DAPrt.Name  DAPort_Name    , JF.DName        Job_DName   , JF.DAddress          Job_DAddress   ,
        U.Id          User_Id        , U.UGrp_Id   User_UGrp_Id   , U.PGrp_Id       User_PGrp_Id, U.Gender_Id          User_Gender_Id ,
        U.Status_Id   User_Status_Id , U.Logon     User_Logon     , U.Name          User_Name   ,
        S.Id          Status_Id      , S.Name      Status_Name    , JF.SDate        Status_Date , JF.SRem              Status_Rem     ,
        DS.Id         Del_Status_Id  , DS.Name     Del_Status_Name, JF.DelNum       Del_Num     , JF.DelDate           Del_Date       ,
        JF.DelName    Del_Name       , JF.DelRem   Del_Rem        ,
        JF.Ship       Job_Ship       , JF.Cons     Job_Cons       , JF.Dist         Job_Dist    , JF.ODist             Job_ODist      ,
        JF.WNet       Job_WNet       , JF.WGros    Job_WGros      , JF.WChrg        Job_WChrg   , JF.Volume            Job_Volume     ,
        JF.ETD        Job_ETD        , JF.ETA      Job_ETA        , JF.ATD          Job_ATD     , JF.ATA               Job_ATA        ,
        JF.MNum       Job_MNum       , JF.MDate    Job_MDate      , JF.HNum         Job_HNum    , JF.HDate             Job_HDate      ,
        JF.nRef       Job_nRef       , JF.POrder   Job_POrder     , JF.SDM          Job_SDM     , JF.LDM               Job_LDM        ,
        JF.CBM        Job_CBM        , JF.OPlace   Job_OPlace     ,
        PKT.Id        Pack_Id        , PKT.Name    Pack_Name      ,
        DK.Id         KDocType_Id    , DK.Name     KDocType_Name  , JF.KDocNum      Job_KDocNum , JF.KDocDate          Job_KDocDate   ,
        JF.Waybill    Job_Waybill    , JF.Truck    Job_Truck      , JF.Driver       Job_Driver  ,
        OPS.Id        OpStatus_Id    , OPS.Name    OpStatus_Name  , JF.OPSRem       Job_OPSRem  ,
        TT.Id         TType_Id       , TT.Name     TType_Name     ,
        JF.ODmrge     Job_ODmrge     , JF.DDmrge   Job_DDmrge     , JF.OverQnt      Job_OverQnt ,
        JF.ArrODate   Job_ArrODate   , JF.LoadDate Job_LoadDate   ,
        JF.DispDate   Job_DispDate   , JF.ArrDDate Job_ArrDDate   ,
        JF.UDate      Job_UDate      , JF.DocDate  Job_DocDate    ,
        JF.OrigRem    Job_OrigRem    , JF.DestRem  Job_DestRem    ,
        CO.Id         Cooling_Id     , CO.Name     Cooling_Name   ,
        CL.Id         Cancel_Id      , CL.Name     Cancel_Name    ,
        JF.Rel_Id     Job_Rel_Id     , JF.Rem      Job_Rem        , JF.vPath        Job_vPath   , JF.OverDist          Job_OverDist   ,
        JF.Ins_User   Job_Ins_User   , JF.Ins_Date Job_Ins_Date   , JF.Upd_User     Job_Upd_User, JF.Upd_Date          Job_Upd_Date
   FROM Fre_Lfr_Job         JF   ,
        Cpy_Period          P    ,
        Cpy_Dept            DP   ,
        Cpy_Unit            UN   ,
        Cpy_Oper            OP   ,
        Fre_MOffer          O    ,
        Fre_MInqry          MQ   ,
        Mng_Cont            C    ,
        Mng_Cont            CR   ,
        Fre_MCntrct         CTRC ,
        Fre_MCntrct         CTRS ,
        Cpy_User            U    ,
        Fre_Driv            DRV  ,
        Fre_Truk            TRK  ,
        Emp_Emp             Emp  ,
        Fre_Cod_Job_Status  S    ,
        Phs_Cod_YesNo       DS   ,
        Fre_Cod_Inco_Term   IT   ,
        Fre_Cod_Pay_Term    PT   ,
        Fre_Cod_Cntry       OCntr,
        Fre_Cod_City        OCty ,
        Fre_Cod_City        OPrt ,
        Fre_Cod_SeaPort     OSPrt,
        Fre_Cod_AirPort     OAPrt,
        Fre_Cod_Cntry       DCntr,
        Fre_Cod_City        DCty ,
        Fre_Cod_City        DPrt ,
        Fre_Cod_SeaPort     DSPrt,
        Fre_Cod_AirPort     DAPrt,
        Fre_Cod_Pack        PKT  ,
        Fre_Cod_KDocType    DK   ,
        Fre_Cod_Oper_Status OPS  ,
        Fre_Cod_Truck_Type  TT   ,
        Phs_Cod_YesNo       CO   ,
        Phs_Cod_YesNo       CL
  WHERE JF.Period_Id  =P.Id
    AND COALESCE(JF.Dept_Id,0)    =DP.Id
    AND COALESCE(JF.Unit_Id,0)    =UN.Id
    AND COALESCE(JF.Oper_Id,0)    =OP.Id
    AND COALESCE(JF.Ofer_Id,0)    =O.Id
    AND COALESCE(O.Inqry_Id,0)    =MQ.Id
    AND COALESCE(JF.Cont_Id,0)    =C.Id
    AND JF.Cont_RId   =CR.Id
    AND JF.ContR_Id   =CTRC.Id
    AND JF.ContR_RId  =CTRS.Id
    AND COALESCE(JF.Owner_Id,0)   =U.Id
    AND COALESCE(JF.Driv_Id,0)    =DRV.Id
    AND COALESCE(JF.Truk_Id,0)    =TRK.Id
    AND COALESCE(JF.Emp_Id,0)     =Emp.Id
    AND COALESCE(JF.Status_Id,0)  =S.Id
    AND COALESCE(JF.DStatus_Id,0) =DS.Id
    AND COALESCE(JF.ITerm_Id,0)   =IT.Id
    AND COALESCE(JF.PTerm_Id,0)   =PT.Id
    AND COALESCE(JF.OCntry_Id,0)  =OCntr.Id
    AND COALESCE(JF.OCity_Id,0)   =OCty.Id
    AND COALESCE(JF.OPort_Id   ,0)=OPrt.Id
    AND COALESCE(JF.OSPort_Id,0)  =OSPrt.Id
    AND COALESCE(JF.OAPort_Id,0)  =OAPrt.Id
    AND COALESCE(JF.DCntry_Id,0)  =DCntr.Id
    AND COALESCE(JF.DCity_Id,0)   =DCty.Id
    AND COALESCE(JF.DPort_Id   ,0)=DPrt.Id
    AND COALESCE(JF.DSPort_Id  ,0)=DSPrt.Id
    AND COALESCE(JF.DAPort_Id  ,0)=DAPrt.Id
    AND COALESCE(JF.Pack_Id,0)    =PKT.Id
    AND COALESCE(JF.KDocType_Id,0)=DK.Id
    AND COALESCE(JF.OpStatus_Id,0)=OPS.Id
    AND COALESCE(JF.TType_Id,0)   =TT.Id
    AND COALESCE(JF.Cooling_Id,0) =CO.Id
    AND COALESCE(JF.Cancel_Id,0)  =CL.Id;

