        JF.Job_Truck        JF_Job_Truck     , JF.Job_Driver       JF_Job_Driver     , JF.OpStatus_Id     JF_OpStatus_Id    , JF.OpStatus_Name     JF_OpStatus_Name  , JF.Job_OPSRem      JF_Job_OPSRem     ,
        JF.TType_Id         JF_TType_Id      , JF.TType_Name       JF_TType_Name     , JF.Job_ODmrge      JF_Job_ODmrge     , JF.Job_DDmrge        JF_Job_DDmrge     , JF.Job_OverQnt     JF_Job_OverQnt    ,
        JF.Job_ArrODate     JF_Job_ArrODate  , JF.Job_LoadDate     JF_Job_LoadDate   , JF.Job_DispDate    JF_Job_DispDate   , JF.Job_ArrDDate      JF_Job_ArrDDate   , JF.Job_UDate       JF_Job_UDate      ,
        JF.Job_DocDate      JF_Job_DocDate   , JF.Job_OrigRem      JF_Job_OrigRem    , JF.Job_DestRem     JF_Job_DestRem    , JF.Cooling_Id        JF_Cooling_Id     , JF.Cooling_Name    JF_Cooling_Name   ,
        JF.Cancel_Id        JF_Cancel_Id     , JF.Cancel_Name      JF_Cancel_Name    , JF.Job_Rel_Id      JF_Job_Rel_Id     , JF.Job_Rem           JF_Job_Rem        , JF.Job_vPath       JF_Job_vPath      ,
        JF.Job_OverDist     JF_Job_OverDist  , JF.Job_Ins_User     JF_Job_Ins_User   , JF.Job_Ins_Date    JF_Job_Ins_Date   , JF.Job_Upd_User      JF_Job_Upd_User   , JF.Job_Upd_Date    JF_Job_Upd_Date   ,
        DC.Id               DBCR_Id          ,
        DC.nOrd             DBCR_nOrd        , DC.Num              DBCR_Num          , DC.dDate            DBCR_dDate       , DP.Id                Dept_Id           , DP.Name             Dept_Name        ,
        OP.Id               Oper_Id          , OP.Name             Oper_Name         , U.Id                Unt_Id           , U.Name               Unt_Name          ,
        To_Number_Compat(To_Char(DC.dDate,'YYYY'))    D_Year            ,
        To_Number_Compat(To_Char(DC.dDate,'MM'))      D_Month           ,
        To_Number_Compat(To_Char(DC.dDate,'DD'))      D_DayOfMonth      ,
        To_Number_Compat(To_Char(DC.dDate,'DDD'))     D_DayOfYear       ,
        To_Number_Compat(To_Char(DC.dDate,'D'))       D_DayOfWeek       ,
        To_Char(DC.dDate,'YYYY-MM')            D_YearMonth       ,
        Loc.Id              Loc_Id           , Loc.Name            Loc_Name          , TrT.Id              Trt_Id           , TrT.Name             Trt_Name          ,
        C.Id                Cont_Id          , C.Name              Cont_Name         , S.Id                Serv_Id          , S.Name               Serv_Name         ,
        I.Id                Item_Id          , I.LName             Item_Name         , Un.Id               Unit_Id          , Un.Name              Unit_Name         ,
        CR.Id               Curn_Id          , CR.Name             Curn_Name         , ST.Id               Status_Id        , ST.Name              Status_Name       ,
        DC.Curn_Rate        DBCR_Curn_Rate   , DC.Qnt              DBCR_Qnt          , DC.Price            DBCR_Price       , DC.CAmt              DBCR_CAmt         ,
        DC.Amt              DBCR_Amt         , DC.nRef             DBCR_nRef         , DC.dRef             DBCR_dRef        ,
        DC.Rem              DBCR_Rem         , DC.IFre_Id          IFre_Id           , DC.DFre_Id          DFre_Id          , DC.CFre_Id           CFre_Id           ,
        DC.Dept_RId         Dept_RId         , DC.Unit_RId         Unit_RId          , DC.Job_RId          Job_RId          , DC.Ord_Id            Ord_Id            ,
        DC.Waybill          DBCR_Waybill     , DC.Period_Id     ,
        DC.Ins_User         DBCR_Ins_User    , DC.Ins_Date        DBCR_Ins_Date      , DC.Upd_User         DBCR_Upd_User   , DC.Upd_Date           DBCR_Upd_Date
   FROM Fre_Lfr_DBCR  DC ,
        Fre_VLfr_Job  JF ,
        Cpy_Unit      U  ,
        Cpy_Dept      DP ,
        Cpy_Oper      OP ,
        Fre_Cod_Loc   Loc,
        Fin_Cod_Trt   TrT,
        Mng_Cont      C  ,
        Mng_Serv      S  ,
        Stor_Item     I  ,
        Cpy_Cod_Unit  Un ,
        Mng_Curn      CR ,
        Phs_Cod_YesNo ST
  WHERE DC.Job_Id          =JF.Job_Id
    AND JF.Dept_Id         =DP.Id
    AND JF.Oper_Id         =OP.Id
    AND JF.Unit_Id         =U.Id
    AND COALESCE(DC.Loc_Id   ,1)=Loc.Id
    AND COALESCE(DC.Trt_Id   ,0)=Trt.Id
    AND COALESCE(DC.Cont_Id  ,0)=C.Id
    AND COALESCE(DC.Serv_Id  ,0)=S.Id
    AND COALESCE(DC.Item_Id  ,0)=I.Id
    AND COALESCE(DC.Unit_Id  ,1)=Un.Id
    AND COALESCE(DC.Curn_Id  ,1)=CR.Id
    AND COALESCE(DC.Status_Id,2)=ST.Id;

CREATE OR REPLACE VIEW Fre_VClr_Job AS
 SELECT
        JF.Id         Job_Id          ,
        P.Id          Period_Id       , P.Num       Period_Num        , P.SDate         Period_SDate   , P.EDate     Period_EDate  ,
        P.Name        Period_Name         ,
        DP.Id         Dept_Id         , DP.Name     Dept_Name         , UN.Id           Unit_Id        , UN.Name     Unit_Name     ,
        OP.Id         Oper_Id         , OP.Name     Oper_Name         , CR.Id           Curn_Id        , CR.Name     Curn_Name     ,
        JF.Curn_Rate                  ,
        MC.Id         JF_Cont_Id      , MC.Name     JF_Cont_Name      ,
        MD.Id         Mode_Id         , MD.Name     Mode_Name         ,
        O.Id          Offer_Id        , O.Num       Offer_Num         , O.dDate         Offer_Date     ,
        MQ.Id         Inqry_Id        , MQ.Num      Inqry_Num         , MQ.dDate        Inqry_Date     ,
        JF.Num        Job_Num         , JF.dDate    Job_Date          , JF.Descr        Job_Descr      ,
        To_Number_Compat(To_Char(JF.dDate,'YYYY'))         D_Year            ,
        To_Number_Compat(To_Char(JF.dDate,'MM'))           D_Month           ,
        To_Number_Compat(To_Char(JF.dDate,'DD'))           D_DayOfMonth      ,
        To_Number_Compat(To_Char(JF.dDate,'DDD'))          D_DayOfYear       ,
        To_Number_Compat(To_Char(JF.dDate,'D'))            D_DayOfWeek       ,
        To_Char(JF.dDate,'YYYY-MM')                 D_YearMonth       ,
        IT.Id         ITerm_Id        , IT.Name     ITerm_Name        , PT.Id           PTerm_Id       , PT.Name              PTerm_Name     ,
        OCntr.Id      OCntry_Id       , OCntr.Name  OCntry_Name       , OCntr.Continent OContinent     , OCntr.Continent_Code OContinent_Code,
        OCty.Id       OCity_Id        , OCty.Name   OCity_Name        ,
        OPrt.Id       OPort_Id        , OPrt.Name   OPort_Name        , OSPrt.Id        OSPort_Id      , OSPrt.Name           OSPort_Name    ,
        OAPrt.Id      OAPort_Id       , OAPrt.Name  OAPort_Name       , JF.OName        Job_OName      , JF.OAddress          Job_OAddress   ,
        DCntr.Id      DCntry_Id       , DCntr.Name  DCntry_Name       , DCntr.Continent DContinent     , DCntr.Continent_Code DContinent_Code,
        DCty.Id       DCity_Id        , DCty.Name   DCity_Name        ,
        DPrt.Id       DPort_Id        , DPrt.Name   DPort_Name        , DSPrt.Id    DSPort_Id   , DSPrt.Name  DSPort_Name   ,
        DAPrt.Id      DAPort_Id       , DAPrt.Name  DAPort_Name       , JF.DName    Job_DName   , JF.DAddress Job_DAddress  ,
        CMD.Id        Comod_Id        , CMD.Name    Comod_Name        ,
        JF.vComd      Job_vComd       , JF.Ship     Job_Ship          , JF.Cons     Job_Cons    , JF.Qnt      Job_Qnt       ,
        JF.Price      Job_Price       ,
        JF.WNet       Job_WNet        , JF.WGros    Job_WGros         , JF.WChrg    Job_WChrg   , JF.Volume   Job_Volume    ,
        JF.Amt        Job_Amt         ,
        JF.CAmt       Job_CAmt        , JF.Comm     Job_Comm          , JF.CComm    Job_CComm   , JF.ETD      Job_ETD       ,
        JF.ETA        Job_ETA         ,
        JF.ATD        Job_ATD         , JF.ATA      Job_ATA           ,
        U.Id          User_Id         , U.UGrp_Id   User_UGrp_Id      , U.PGrp_Id   User_PGrp_Id, U.Gender_Id User_Gender_Id,
        U.Status_Id   User_Status_Id  , U.Logon     User_Logon        , U.Name      User_Name   ,
        S.Id          Status_Id       , S.Name      Status_Name       , JF.SDate    Status_Date , JF.SRem     Status_Rem    ,
        DS.Id         Del_Status_Id   , DS.Name     Del_Status_Name   , JF.DelNum   Del_Num     , JF.DelDate  Del_Date      ,
        JF.DelPerson  Del_Person      ,
        JF.DCust      Job_DCust       , JF.DueDate  Job_DueDate       , JF.MNum     Job_MNum    , JF.MDate    Job_MDate     ,
        JF.HNum       Job_HNum        ,
        JF.HDate      Job_HDate       , JF.ENum     Job_ENum          , JF.EDate    Job_EDate   , JF.FNum     Job_FNum      ,
        JF.FDate      Job_FDate       ,
        AL.Id         AirLine_Id      , AL.Name     AirLine_Name      , SL.Id       ShipLine_Id , SL.Name     ShipLine_Name ,
        JF.nRef       Job_nRef        , JF.BRef     Job_BRef          , JF.POrder   Job_POrder  ,
        TR.Id         Track_Id        , TR.Name     Track_Name        ,
        JF.LDM        Job_LDM         , JF.CBM      Job_CBM           , JF.CMRDate  Job_CMRDate ,
        PKT.Id        Pack_Id         , PKT.Name    Pack_Name         ,
        DK.Id         KDocType_Id     , DK.Name     KDocType_Name     , JF.KDocNum  Job_KDocNum , JF.KDocDate Job_KDocDate  ,
        JF.Waybill    Job_Waybill     ,
        DI.Id         IDocType_Id     , DI.Name     IDocType_Name     , JF.IDocNum  Job_IDocNum , JF.IDocDate Job_IDocDate  ,
        OD.Id         ODocType_Id     , OD.Name     ODocType_Name     , JF.ODocNum  Job_ODocNum , JF.ODocDate Job_ODocDate  ,
        JF.TripNo     Job_TripNo      ,
        TT.Id         TType_Id        , TT.Name     TType_Name        , JF.Rel_Id   Job_Rel_Id  , JF.Rem      Job_Rem       ,
        PS.Id         PShare_Status_Id, PS.Name     PShare_Status_Name,
        JF.Ins_User   Job_Ins_User    , JF.Ins_Date Job_Ins_Date      , JF.Upd_User Job_Upd_User, JF.Upd_Date Job_Upd_Date
   FROM Fre_CLR_Job         JF   ,
        Cpy_Period          P    ,
        Cpy_Dept            DP   ,
        Cpy_Unit            UN   ,
        Cpy_Oper            OP   ,
        Mng_Cont            MC   ,
        Fre_MOffer          O    ,
        Fre_MInqry          MQ   ,
        Mng_Curn            CR   ,
        Fre_Cod_Inco_Term   IT   ,
        Fre_Cod_Pay_Term    PT   ,
        Phs_Cod_YesNo       MD   ,
        Fre_Cod_Comod       CMD  ,
        Cpy_User            U    ,
        Fre_Cod_Job_Status  S    ,
        Phs_Cod_YesNo       DS   ,
        Fre_Cod_Airline     AL   ,
        Fre_Cod_Shipline    SL   ,
        Fre_Cod_Cntry       OCntr,
        Fre_Cod_City        OCty ,
        Fre_Cod_City        OPrt ,
        Fre_Cod_SeaPort     OSPrt,
        Fre_Cod_AirPort     OAPrt,
        Fre_Cod_Cntry       DCntr,
        Fre_Cod_City        DCty ,
        Fre_Cod_City        DPrt ,
        Fre_Cod_SeaPort     DSPrt,
        Fre_Cod_AirPort     DAPrt,
        Fre_Cod_Track       TR   ,
        Fre_Cod_Pack        PKT  ,
        Fre_Cod_KDocType    DK   ,
        Fre_Cod_IDocType    DI   ,
        Fre_Cod_ODocType    OD   ,
        Fre_Cod_Truck_Type  TT   ,
        Phs_Cod_YesNo       PS
  WHERE JF.Period_Id         =P.Id
    AND COALESCE(JF.Dept_Id    ,0)=DP.Id
    AND COALESCE(JF.Unit_Id    ,0)=UN.Id
    AND COALESCE(JF.Oper_Id    ,0)=OP.Id
    AND JF.Cont_Id           =MC.Id
    AND COALESCE(JF.Ofer_Id    ,0)=O.Id
    AND COALESCE(O.Inqry_Id    ,0)=MQ.Id
    AND COALESCE(JF.Curn_Id    ,1)=CR.Id
    AND COALESCE(JF.ITerm_Id   ,0)=IT.Id
    AND COALESCE(JF.PTerm_Id   ,0)=PT.Id
    AND COALESCE(JF.Mode_Id    ,0)=MD.Id
    AND COALESCE(JF.Comod_Id   ,0)=CMD.Id
    AND COALESCE(JF.Owner_Id   ,0)=U.Id
    AND COALESCE(JF.Status_Id  ,0)=S.Id
    AND COALESCE(JF.DStatus_Id ,0)=DS.Id
    AND COALESCE(JF.AirLine_Id ,0)=AL.Id
    AND COALESCE(JF.ShipLine_Id,0)=SL.Id
    AND COALESCE(JF.OCntry_Id  ,0)=OCntr.Id
    AND COALESCE(JF.OCity_Id   ,0)=OCty.Id
    AND COALESCE(JF.OPort_Id   ,0)=OPrt.Id
    AND COALESCE(JF.OSPort_Id  ,0)=OSPrt.Id
    AND COALESCE(JF.OAPort_Id  ,0)=OAPrt.Id
    AND COALESCE(JF.DCntry_Id  ,0)=DCntr.Id
    AND COALESCE(JF.DCity_Id   ,0)=DCty.Id
    AND COALESCE(JF.DPort_Id   ,0)=DPrt.Id
    AND COALESCE(JF.DSPort_Id  ,0)=DSPrt.Id
    AND COALESCE(JF.DAPort_Id  ,0)=DAPrt.Id
    AND COALESCE(JF.Track_Id   ,0)=TR.Id
    AND COALESCE(JF.Pack_Id    ,0)=PKT.Id
    AND COALESCE(JF.KDocType_Id,0)=DK.Id
    AND COALESCE(JF.IDocType_Id,0)=DI.Id
    AND COALESCE(JF.ODocType_Id,0)=OD.Id
    AND COALESCE(JF.TType_Id   ,0)=TT.Id
    AND COALESCE(JF.PSStatus_Id,0)=PS.Id;

CREATE OR REPLACE VIEW Fre_VClr_DBCR AS
 SELECT
        DC.Id            DBCR_Id          ,
        JF.Job_Id                         ,
        JF.Period_Id     JF_Period_Id     , JF.Period_Num   , JF.Period_SDate , JF.Period_EDate  ,
        JF.Period_Name   JF_Period_Name   ,                           
        JF.Dept_Id       JF_Dept_Id       , JF.Dept_Name   JF_Dept_Name , 
        JF.Oper_Id       JF_Oper_Id       , JF.Oper_Name   JF_Oper_Name , 
        JF.Curn_Rate     JF_Curn_Rate     ,
        JF.Unit_Id       JF_Unit_Id       , JF.Unit_Name   JF_Unit_Name ,          
        JF.Curn_Id       JF_Curn_Id       , JF.Curn_Name   JF_Curn_Name ,
        JF.Mode_Id                        , JF.Mode_Name                ,          
        JF.Job_Num                        , JF.Job_Date                 , JF.Job_Descr    ,
        JF.ITerm_Id                       , JF.ITerm_Name               , JF.PTerm_Id     , JF.PTerm_Name    ,
        JF.OCntry_Id                      , JF.OCntry_Name              ,
        JF.OContinent                     , JF.OContinent_Code          , JF.OCity_Id     , JF.OCity_Name    ,
        JF.OPort_Id                       , JF.OPort_Name               , JF.OSPort_Id    , JF.OSPort_Name   ,
        JF.OAPort_Id                      , JF.OAPort_Name              , JF.Job_OName    , JF.Job_OAddress  ,
        JF.DCntry_Id                      , JF.DCntry_Name              ,
        JF.DContinent                     , JF.DContinent_Code          , JF.DCity_Id     , JF.DCity_Name    ,
        JF.DPort_Id                       , JF.DPort_Name               , JF.DSPort_Id    , JF.DSPort_Name   ,
        JF.DAPort_Id                      , JF.DAPort_Name              , JF.Job_DName    , JF.Job_DAddress  ,
        JF.Comod_Id                       , JF.Comod_Name               ,
        JF.Job_vComd                      , JF.Job_Ship                 , JF.Job_Cons     , JF.Job_Qnt       ,
        JF.Job_Price                      ,
        JF.Job_WNet                       , JF.Job_WGros                , JF.Job_WChrg    , JF.Job_Volume    ,
        JF.Job_Amt                        ,
        JF.Job_CAmt                       , JF.Job_Comm                 , JF.Job_CComm    , JF.Job_ETD       ,
        JF.Job_ETA                        ,
        JF.Job_ATD                        , JF.Job_ATA                  ,                 
        JF.User_Id                        , JF.User_UGrp_Id             , JF.User_PGrp_Id , JF.User_Gender_Id,
        JF.User_Status_Id                 , JF.User_Logon               , JF.User_Name    ,
        JF.Status_Id                        JF_Status_Id                , JF.Status_Name    JF_Status_Name   ,
        JF.Status_Date                                                  , JF.Status_Rem   ,
        JF.Del_Status_Id                  , JF.Del_Status_Name          , JF.Del_Num      , JF.Del_Date      ,
        JF.Del_Person                     ,
        JF.Job_DCust                      , JF.Job_DueDate              , JF.Job_MNum     , JF.Job_MDate     ,
        JF.Job_HNum                       ,
        JF.Job_HDate                      , JF.Job_ENum                 , JF.Job_EDate    , JF.Job_FNum      ,
        JF.Job_FDate                      ,
        JF.AirLine_Id                     , JF.AirLine_Name             , JF.ShipLine_Id  , JF.ShipLine_Name ,
        JF.Job_nRef                       , JF.Job_BRef                 , JF.Job_POrder   ,
        JF.Track_Id                       , JF.Track_Name               ,                 
        JF.Job_LDM                        , JF.Job_CBM                  , JF.Job_CMRDate  ,
        JF.Pack_Id                        , JF.Pack_Name                ,                 
        JF.KDocType_Id                    , JF.KDocType_Name            , JF.Job_KDocNum  , JF.Job_KDocDate  ,
        JF.Job_Waybill                    ,                                               
        JF.IDocType_Id                    , JF.IDocType_Name            , JF.Job_IDocNum  , JF.Job_IDocDate  ,
        JF.ODocType_Id                    , JF.ODocType_Name            , JF.Job_ODocNum  , JF.Job_ODocDate  ,
        JF.Job_TripNo                     ,
        JF.TType_Id                       , JF.TType_Name               , JF.Job_Rel_Id   , JF.Job_Rem       ,
        JF.PShare_Status_Id               , JF.PShare_Status_Name       ,                 
        JF.Job_Ins_User                   , JF.Job_Ins_Date             , JF.Job_Upd_User , JF.Job_Upd_Date  ,
        DC.nOrd       DBCR_nOrd           , DC.Num        DBCR_Num      , DC.dDate       DBCR_dDate          ,
        DP.Id         Dept_Id             , DP.Name       Dept_Name     ,
        OP.Id         Oper_Id             , OP.Name       Oper_Name     ,
        U.Id          Unt_Id              , U.Name        Unt_Name      ,
        To_Number_Compat(To_Char(DC.dDate,'YYYY'))               D_Year        ,
        To_Number_Compat(To_Char(DC.dDate,'MM'))                 D_Month       ,
        To_Number_Compat(To_Char(DC.dDate,'DD'))                 D_DayOfMonth  ,
        To_Number_Compat(To_Char(DC.dDate,'DDD'))                D_DayOfYear   ,
        To_Number_Compat(To_Char(DC.dDate,'D'))                  D_DayOfWeek   ,
        To_Char(DC.dDate,'YYYY-MM')                       D_YearMonth   ,
        Loc.Id        Loc_Id              , Loc.Name      Loc_Name      , TrT.Id        Trt_Id        , TrT.Name      Trt_Name      ,
        C.Id          Cont_Id             , C.Name        Cont_Name     , S.Id          Serv_Id       , S.Name        Serv_Name     ,
        I.Id          Item_Id             , I.LName       Item_Name     , Un.Id         Unit_Id       , Un.Name       Unit_Name     ,
        CR.Id         Curn_Id             , CR.Name       Curn_Name     , ST.Id         Status_Id     , ST.Name       Status_Name   ,
        DC.Curn_Rate  DBCR_Curn_Rate      , DC.Qnt        DBCR_Qnt      , DC.Price      DBCR_Price    , DC.CAmt       DBCR_CAmt     ,
        DC.Amt        DBCR_Amt            , DC.nRef       DBCR_nRef     , DC.dRef       DBCR_dRef     ,
        DC.Rem        DBCR_Rem            , DC.IFre_Id    IFre_Id       , DC.DFre_Id    DFre_Id       , DC.CFre_Id    CFre_Id       ,
        DC.Dept_RId   Dept_RId            , DC.Unit_RId   Unit_RId      , DC.Job_RId    Job_RId       , DC.Ord_Id     Ord_Id        ,
        DC.Waybill    DBCR_Waybill        , DC.Period_Id ,
        DC.Ins_User   DBCR_Ins_User       , DC.Ins_Date   DBCR_Ins_Date , DC.Upd_User   DBCR_Upd_User , DC.Upd_Date   DBCR_Upd_Date
   FROM Fre_CLR_DBCR  DC ,
        Fre_VClr_Job  JF ,
        Cpy_Dept      DP ,
        Cpy_Oper      OP ,
        Cpy_Unit      U  ,
        Fre_Cod_Loc   Loc,
        Fin_Cod_Trt   TrT,
        Mng_Cont      C  ,
        Mng_Serv      S  ,
        Stor_Item     I  ,
        Cpy_Cod_Unit  Un ,
        Mng_Curn      CR ,
        Phs_Cod_YesNo ST
  WHERE DC.Job_Id          =JF.Job_Id
    AND JF.Dept_Id         =DP.Id
    AND JF.Oper_Id         =OP.Id
    AND JF.Unit_Id         =U.Id
    AND COALESCE(DC.Loc_Id   ,1)=Loc.Id
    AND COALESCE(DC.Trt_Id   ,0)=Trt.Id
    AND COALESCE(DC.Cont_Id  ,0)=C.Id
    AND COALESCE(DC.Serv_Id  ,0)=S.Id
    AND COALESCE(DC.Item_Id  ,0)=I.Id
    AND COALESCE(DC.Unit_Id  ,1)=Un.Id
    AND COALESCE(DC.Curn_Id  ,1)=CR.Id
    AND COALESCE(DC.Status_Id,2)=ST.Id;

CREATE OR REPLACE VIEW Fre_VDBCR AS
 SELECT
        1 AS Type,
        IFR.Dept_Id               Dept_Id       , IFR.Dept_Name       Dept_Name       ,
        IFR.Oper_Id               Oper_Id       , IFR.Oper_Name       Oper_Name       ,
        IFR.Unt_Id                Unt_Id        , IFR.Unt_Name        Unt_Name        ,
        IFR.DBCR_Id               DBCR_Id       , 
        IFR.Job_Id                Job_Id        , IFR.Job_Num         Job_Num         , IFR.Job_Date      Job_Date      ,
        IFR.JF_Period_Id          JF_Period_Id  , IFR.JF_Period_Name  JF_Period_Name  ,
        IFR.DBCR_nOrd             DBCR_nOrd     , IFR.DBCR_Num        DBCR_Num        , IFR.DBCR_dDate    DBCR_dDate    ,
        IFR.D_Year                D_Year        ,                         
        IFR.D_Month               D_Month       ,                         
        IFR.D_DayOfMonth          D_DayOfMonth  ,                         
        IFR.D_DayOfYear           D_DayOfYear   ,                         
        IFR.D_DayOfWeek           D_DayOfWeek   ,                         
        IFR.D_YearMonth           D_YearMonth   ,                         
        IFR.Loc_Id                Loc_Id        , IFR.Loc_Name        Loc_Name        , IFR.Trt_Id        Trt_Id       , IFR.Trt_Name      Trt_Name     ,
        IFR.Cont_Id               Cont_Id       , IFR.Cont_Name       Cont_Name       , IFR.Serv_Id       Serv_Id      , IFR.Serv_Name     Serv_Name    ,
        IFR.Item_Id               Item_Id       , IFR.Item_Name       Item_Name       , IFR.Unit_Id       Unit_Id      , IFR.Unit_Name     Unit_Name    ,
        IFR.Curn_Id               Curn_Id       , IFR.Curn_Name       Curn_Name       , IFR.Status_Id     Status_Id    , IFR.Status_Name   Status_Name  ,
        IFR.DBCR_Curn_Rate        DBCR_Curn_Rate, IFR.DBCR_Qnt        DBCR_Qnt        , IFR.DBCR_Price    DBCR_Price   , IFR.DBCR_CAmt     DBCR_CAmt    ,
        IFR.DBCR_Amt              DBCR_Amt      , IFR.DBCR_nRef       DBCR_nRef       , IFR.DBCR_dRef     DBCR_dRef    ,                   
        IFR.DBCR_Rem              DBCR_Rem      , IFR.IFre_Id         IFre_Id         , IFR.DFre_Id       DFre_Id      , IFR.CFre_Id       CFre_Id      ,
        IFR.Dept_RId              Dept_RId      , IFR.Unit_RId        Unit_RId        , IFR.Job_RId       Job_RId      , IFR.Ord_Id        Ord_Id       ,
        IFR.DBCR_Waybill          DBCR_Waybill  , IFR.Period_Id       DBCR_Period_Id  ,                                                                                        
        IFR.DBCR_Ins_User         DBCR_Ins_User , IFR.DBCR_Ins_Date   DBCR_Ins_Date   , IFR.DBCR_Upd_User DBCR_Upd_User, IFR.DBCR_Upd_Date DBCR_Upd_Date
   FROM Fre_VIfr_DBCR IFR
  UNION ALL
 SELECT
        2,
        LFR.Dept_Id               Dept_Id       , LFR.Dept_Name       Dept_Name       ,
        LFR.Oper_Id               Oper_Id       , LFR.Oper_Name       Oper_Name       ,
        LFR.Unt_Id                Unt_Id        , LFR.Unt_Name        Unt_Name        ,
        LFR.DBCR_Id               DBCR_Id       ,                                                                                             
        LFR.JF_Job_Id             Job_Id        , LFR.JF_Job_Num      Job_Num         , LFR.JF_Job_Date   Job_Date     ,
        LFR.JF_Period_Id          JF_Period_Id  , LFR.JF_Period_Name  JF_Period_Name  ,        
        LFR.DBCR_nOrd             DBCR_nOrd     , LFR.DBCR_Num        DBCR_Num        , LFR.DBCR_dDate    DBCR_dDate   ,                      
        LFR.D_Year                D_Year        ,                                                                                              
        LFR.D_Month               D_Month       ,                                                                                              
        LFR.D_DayOfMonth          D_DayOfMonth  ,                                                                                             
        LFR.D_DayOfYear           D_DayOfYear   ,                                                                                              
        LFR.D_DayOfWeek           D_DayOfWeek   ,                                                                                              
        LFR.D_YearMonth           D_YearMonth   ,                                                                                              
        LFR.Loc_Id                Loc_Id        , LFR.Loc_Name        Loc_Name        , LFR.Trt_Id        Trt_Id        , LFR.Trt_Name      Trt_Name     ,
        LFR.Cont_Id               Cont_Id       , LFR.Cont_Name       Cont_Name       , LFR.Serv_Id       Serv_Id       , LFR.Serv_Name     Serv_Name    ,
        LFR.Item_Id               Item_Id       , LFR.Item_Name       Item_Name       , LFR.Unit_Id       Unit_Id       , LFR.Unit_Name     Unit_Name    ,
        LFR.Curn_Id               Curn_Id       , LFR.Curn_Name       Curn_Name       , LFR.Status_Id     Status_Id     , LFR.Status_Name   Status_Name  ,
        LFR.DBCR_Curn_Rate        DBCR_Curn_Rate, LFR.DBCR_Qnt        DBCR_Qnt        , LFR.DBCR_Price    DBCR_Price    , LFR.DBCR_CAmt     DBCR_CAmt    ,
        LFR.DBCR_Amt              DBCR_Amt      , LFR.DBCR_nRef       DBCR_nRef       , LFR.DBCR_dRef     DBCR_dRef     ,                   
        LFR.DBCR_Rem              DBCR_Rem      , LFR.IFre_Id         IFre_Id         , LFR.DFre_Id       DFre_Id       , LFR.CFre_Id       CFre_Id      ,
        LFR.Dept_RId              Dept_RId      , LFR.Unit_RId        Unit_RId        , LFR.Job_RId       Job_RId       , LFR.Ord_Id        Ord_Id       ,
        LFR.DBCR_Waybill          DBCR_Waybill  , LFR.Period_Id       DBCR_Period_Id  ,                                                                                           
        LFR.DBCR_Ins_User         DBCR_Ins_User , LFR.DBCR_Ins_Date   DBCR_Ins_Date   , LFR.DBCR_Upd_User DBCR_Upd_User , LFR.DBCR_Upd_Date DBCR_Upd_Date
   FROM Fre_VLfr_DBCR LFR
  UNION ALL
