        CLR.DBCR_Curn_Rate        DBCR_Curn_Rate, CLR.DBCR_Qnt        DBCR_Qnt        , CLR.DBCR_Price   DBCR_Price      , CLR.DBCR_CAmt   DBCR_CAmt    ,
        CLR.DBCR_Amt              DBCR_Amt      , CLR.DBCR_nRef       DBCR_nRef       , CLR.DBCR_dRef    DBCR_dRef       ,                 
        CLR.DBCR_Rem              DBCR_Rem      , CLR.IFre_Id         IFre_Id         , CLR.DFre_Id      DFre_Id         , CLR.CFre_Id     CFre_Id      ,
